	private void addChanged(AddressRange toAdd) {
		lock (changed) {
			changed.add(toAdd);
			changeDebouncer.contact(null);
		}
	}

	private AddressSetView clearChanged(bool get) {
		lock (changed) {
			AddressSetView result = get ? new AddressSet(changed) : null;
			changed.clear();
			return result;
		}
	}

